    "year": "2025",
    "description": "在梅卡伊纳部落安顿下来后，杰克·萨利与奈蒂莉一家仍深陷失去长子的悲痛之中，奈蒂莉对人类的仇恨也愈发强烈。由于人类少年“蜘蛛”无法长期依靠呼吸设备生活，杰克一家决定陪同“风之商人”护送他前往更适合人类居住的地方。然而途中，商队突然遭到“灰烬族”的袭击。这个家园曾被灾难摧毁、并因此背弃大地之母爱娃的纳威人族群，在首领瓦朗的带领下烧毁船只、掠夺物资，使萨利一家再度陷入危机。与此同时，迈尔斯·夸里奇上校依然没有放弃对杰克的追踪。面对来自人类以及纳威人内部的新威胁，原本尚未走出伤痛的一家人不得不再次为了彼此和潘多拉的未来而战……",
