    "description": "当一架美国核子潜艇的队员在雷达荧幕上发现一件不明物体之际，潜艇突然被撞击，沉没于一个无底深渊，由巴德为首的钻油工人奉命前往拯救潜艇队员，这群拯救队伍还包括科菲中尉率领的水底军事专家，科菲中尉的秘密任务是找回艇上的150枚核弹头，然而当拯救队到达了一个位于水面下2000多英尺深的石层上时，遇到了种种前所未有的困难。先是海面上的风暴和器材的不足给工作带来阻碍，然后是潜水仓周围有奇怪的物体出现给人带来混乱，在万分危机的时刻，科菲中尉却因为一意孤行而导致一枚核弹坠向暗藏不明生物的深渊……",
