    "description": "1944年，诺曼底登陆期间。经历奥马哈海滩的惨烈战斗后，约翰·米勒上尉突然接到一项特殊命令：深入德军控制区，寻找失散的伞兵詹姆斯·瑞恩。瑞恩家中四兄弟均在军中服役，其中三人已经先后阵亡，为了避免他们的母亲失去最后一个儿子，美军决定将瑞恩找到并安全送回家。米勒只得带领七名士兵离开正在推进的部队，深入危机四伏的法国战场寻找一个素未谋面的人。随着搜寻不断深入，小队不仅要面对随时可能出现的德军，也开始无法回避同一个问题：为了拯救一个人的生命，让更多人冒险甚至牺牲，究竟是否值得……",
