    "description": "亿万富豪约翰·哈蒙德利用先进的遗传技术，从封存在琥珀中的远古蚊子血液里提取恐龙DNA，在努布拉岛成功复活了早已灭绝的恐龙，并建造了一座前所未有的主题公园“侏罗纪公园”。在正式开放之前，他邀请古生物学家艾伦·格兰特、艾丽·塞特勒和数学家伊恩·马尔科姆等人登岛，对公园的安全性进行评估。然而就在众人亲眼见证这些史前巨兽带来的震撼时，一场人为造成的系统故障让岛上的安全设施逐渐失效。失去电网与控制系统保护后，原本被关在围栏中的恐龙开始威胁岛上所有人的生命……",
