    "title": "风之谷",
    "originalTitle": "風の谷のナウシカ",
    "type": "movie",
    "year": "1984",
    "description": "在毁灭工业文明的“火之七日”过去一千年后，世界被散发有毒瘴气的“腐海”逐渐覆盖，生活其中的巨大虫群也让幸存的人类时刻面临威胁。依靠海风阻挡腐海孢子的风之谷，是少数仍能安宁生活的地方。风之谷公主娜乌西卡善于御风，并能够感知王虫等生物的心意，始终试图理解这片被人类畏惧的世界。一天，一架多鲁美奇亚运输机意外坠毁在风之谷，机上竟载着在“火之七日”中毁灭世界的古代兵器“巨神兵”。为了争夺巨神兵，多鲁美奇亚军队随后进入风之谷，使这个宁静的小国骤然卷入战争。面对人类之间不断升级的冲突，以及腐海与王虫带来的危机，娜乌西卡不得不为守护家园踏上新的旅程……",
