    "type": "movie",
    "year": "2008",
    "description": "5岁的宗介和妈妈理莎住在海边小城的悬崖上。一天，他在岸边发现了一条被困在玻璃瓶里的小金鱼，并将她救了出来，给她取名“波妞”。来自海底世界的波妞很快喜欢上了宗介，宗介也答应会一直保护她。然而波妞的父亲藤本并不愿女儿留在人类世界，强行将她带回海底。无法忘记宗介的波妞却下定决心，要再次回到他的身边，甚至希望真正变成人类。为了兑现这份小小却坚定的心愿，波妞再次奔向陆地，也让原本平静的海边小城迎来一场意想不到的奇幻冒险……",
