    "type": "movie",
    "year": "2002",
    "description": "故事始于2046年，为了追捕侵袭火星的外星人多鲁米斯星人，宇宙探索舰Lysithea号在各地挑选先发人员，初中生美加子（武藤寿美 配）也成为一名宇宙员。开始了辗转于火星、太空基地、木星、冥王星等各地的演习。美加子离开地球后，她的同班同学小昇（铃木千寻 配）仍然能收到来自宇宙的问候——美加子时常发来短信告知近况，只是随着距离的扩大，短信送达地球的时间就会越来越长。“有一天一定能再见面吧！”对方都这么想着。可是，美加子终于杳无音信了。8年后，小昇在报纸上读到了8年前宇宙军和多鲁米斯星人恶战且几乎无人生寰的新闻。此时手机突然响了：“24岁的小昇你好，我是15岁的美加子哦！……”手机屏幕上映出这样的话来。",
