    "description": "　　欧洲雇佣兵威廉在被囚禁长城期间，发现了这一世间最大奇迹之一背后的惊人秘密。当一波又一波可怕的掠食生物将这座巨型城墙重重围困之时，威廉对财富的追寻演变为一段通往英雄主义的旅程。他加入了一支由精英勇士们组成的大军，共同对抗令人无法想象的强大力量。",
