    "title": "金陵十三钗",
    "originalTitle": "金陵十三釵",
    "type": "movie",
    "year": "2011",
    "description": "1937年，日军入侵南京，战火中的古城沦为废墟，众多中国军民被困其中。一支十余人的国军德械教导队余部在李教官指挥下，从日军手中救出一批教会学校女学生，也因此失去了撤离南京的机会。幸免于难的书娟等学生返回文彻斯特教堂，与此同时，受雇前来收殓神父遗体的美国人约翰·米勒也来到这里。随着城中局势不断恶化，十四名来自秦淮河畔的风尘女子闯入教堂寻求庇护，其中精通英语的玉墨希望借助约翰的外国人身份获得更多保护。然而，教堂的围墙并不能真正隔绝战争，当日军的威胁一步步逼近，这群原本身份、经历各不相同的人，也不得不共同面对生死抉择……",
