    "description": "白手起家的富豪刘轩拍下一块沿海地皮，并与李若兰合作推进填海开发，使用的声纳技术却严重威胁着附近海域的生态环境，也迫使隐藏其中的人鱼一族逃到废弃沉船中艰难生存。为了阻止填海计划，人鱼一族派出珊珊接近并刺杀刘轩。没想到在一次次阴差阳错的行动中，珊珊与刘轩逐渐产生感情，而这段意外的相遇，也开始改变两人与人鱼一族的命运……",
