    "year": "1993",
    "description": "江南四大才子之首唐伯虎才华横溢，却有着旁人不知的烦恼。面对意图拉拢自己图谋大事的宁王，他只想设法脱身，过些自在日子。一次与好友出游时，唐伯虎偶遇华府丫鬟秋香，并对她一见钟情。为了接近心上人，他费尽心思混入华府，化名“华安”成为家丁，由此闹出一连串令人啼笑皆非的故事。然而随着唐伯虎与秋香逐渐靠近，他也发现华府与唐家之间隐藏着一段旧日恩怨，而虎视眈眈的宁王也再次找上门来……",
