    "title": "喜剧之王",
    "originalTitle": "喜劇之王",
    "type": "movie",
    "year": "1999",
    "description": "尹天仇一直梦想成为真正的演员，却只能在片场四处跑龙套，还常常因为过分认真而遭到导演和工作人员嫌弃。没有戏拍的时候，他就在街坊福利会开设演员训练班，坚持钻研自己热爱的表演。一天，舞女柳飘飘为了学习如何在客人面前演戏来到训练班，与这个落魄却认真的“演员”相识。两个同样不被生活善待的人在一次次相处中逐渐靠近，而尹天仇也终于等来了一个可能改变自己命运的演出机会。面对爱情、尊严与始终遥不可及的演员梦想，他仍固执地相信，总有一天自己能够真正站在属于自己的舞台上……",
