    "originalTitle": "國產凌凌漆",
    "type": "movie",
    "year": "1994",
    "description": "长期被上级弃用的后备特工凌凌漆早已沦为街头卖肉摊主。一天，一件价值连城的恐龙头骨被神秘的“金枪客”盗走，由于任务危险且线索有限，凌凌漆意外再次受到征召，奉命前往香港追回失窃的国宝。临行前，同样落魄的特工达闻西还为他准备了一批稀奇古怪的武器道具。抵达香港后，凌凌漆与联络人李香琴碰头，并循着线索展开调查。然而随着行动深入，他逐渐发现香琴似乎另有目的，而“金枪客”的背后也隐藏着远比盗窃恐龙头骨更加复杂的阴谋。这个看似不靠谱的落魄特工，也因此被卷入一场危机四伏又荒诞离奇的较量……",
