    "originalTitle": "Life of Pi",
    "type": "movie",
    "year": "2012",
    "description": "一名作家偶然得知了派·帕帖尔不同寻常的人生经历，并听他讲起少年时代的往事。派从小在父亲经营的动物园中长大，对动物、信仰与世界始终怀有强烈的好奇。17岁那年，父母决定带着全家和部分动物离开印度，乘船前往加拿大开始新的生活。然而航行途中，一场突如其来的暴风雨令货船沉没，派侥幸登上一艘救生艇，在茫茫太平洋上开始漂流。更加不可思议的是，与他一同困在海上的，还有一只名叫理查德·帕克的孟加拉虎。面对无边的大海、饥饿与随时可能袭来的危险，一人一虎不得不在彼此戒备中寻找共同生存下去的方法，一段超乎想象的奇幻漂流由此展开……",
