    "description": "达什伍德夫人与她的女儿们——埃丽诺、玛丽安及尚在豆蔻年华的假小子玛格丽特，在父亲去世后惨遭驱逐，失去了家园与遗产继承权。法律规定，宏伟的诺兰庄园必须传予他与前妻所生之子、即姑娘们的异母兄长约翰，而约翰的人生伴侣是那位表面优雅却精于算计的范妮。正当贫困的达什伍德一家即将陷入更深窘境时，达什伍德夫人的表亲约翰·米德尔顿爵士伸出援手，将她们安置于自己广阔的德文郡庄园内一处名为巴顿小屋的新居。",
