    "type": "movie",
    "year": "2019",
    "description": "效力于美国国防情报局的特工亨利·布罗根是一名顶尖狙击手，在他的职业生涯中，曾奉命扫除许多威胁国家安全的恐怖分子。执行任务时的他下手果断，毫不迟疑。可是最后一次任务险些失手，却让他产生了动摇，进而提出解甲归田。怎奈放下屠刀的他，偶 然听到了一个有关国家机密的大事，随即便招来杀人之祸。在躲过政府第一次围剿之后，他偕同因监视自己而意外被卷入其中的女特工丹妮展开逃亡，投奔昔日战友巴伦。未曾想新的杀手阴魂不散，尾随而至。更令亨利惊讶的是，追杀他的竟是年轻了23岁的另一个自己……",
