    "type": "movie",
    "year": "1990",
    "description": "王家卫这部突破性的第二部长片，标志着其标志性迷离风格的首次盛放。作为包含《花样年华》与《2046》的松散系列首章，这部令人沉醉的存在主义遐思如梦般游弋于1960年代的香港。一群迷惘的二十代青年——包括寻找生母的叛逆浪子（张国荣 饰）、对他痴情无果的哀怨女子（张曼玉 饰），以及卷入他们感情漩涡的警察（刘德华 饰）——在挫败的欲望之舞中聚散离合。这是导演与摄影师杜可风的首次合作，其镜头赋予影片朦胧梦幻的瑰丽质感；亦是梁朝伟的惊鸿一瞥，为未竟的续篇埋下引线。本片以激昂之势首次展露王家卫对时间、渴望、错位与无尽追寻人际联结的标志性主题。[标准收藏]",
