    "title": "放·逐",
    "originalTitle": "放‧逐",
    "type": "movie",
    "year": "2006",
    "description": "杀手江贵和（张家辉 饰）为让妻子阿静（何超仪 饰）与孩子安稳生活，决定重返澳门落地生根。然而昔日好兄弟火（黄秋生 饰）与波（林雪 饰）奉大佬大飞（任达华 饰）之命前来杀他，另一对好兄弟泰（吴镇宇 饰）与猫（张耀扬 饰）却为情义出手保护。五人冲突一触即发。念及旧日情谊，四人最终让江贵和为家庭接下最后一宗买卖。\r 乱世中的Liberdade酒店罪恶暗藏，四人随江贵和来到此地，并与老板谢夫（张兆辉 饰）会面。谢夫提出两个选择：一是暗杀澳门大佬蛋卷强（林家栋 饰），二是抢夺一吨黄金。江贵和选择前者，却在行动中丧生。阿静认定火等人为杀夫仇人，誓要追杀到底。\r 宿命安排下，火等四人意外来到抢金地点，在冲突中夺得黄金，并结识神枪手陈警司（任贤齐 饰），众人惺惺相惜。正当一行人准备远走高飞之际，火接到大飞来电，得知阿静与孩子已落入其手中。\r 火四人得知阿静被困酒店，毅然折返，成功救出母子。面对大飞的重重人马，他们早已决心豁出性命，迎战最终对决……",
