    "originalTitle": "Double Team",
    "type": "movie",
    "year": "1997",
    "description": "　　杰克（尚格·云顿 Jean-Claude Van Damme 饰）曾经是一名隶属于美国中央情报局的反恐情报人员，如今已经退休的他来到了法国，和妻子凯瑟琳（娜塔莎·兰丁格尔 Natacha Lindinger 饰）一同享受起了闲散而又平静的生活。一个名叫仕达罗（米基·洛克 Mickey Rourke 饰）的恐怖分子引起了情报局的恐慌，为了将他制服，情报局请求业务能力优秀的杰克重新出山，杰克欣然应允。  　　在一次交锋中，杰克对仕达罗妻儿的仁慈让仕达罗得以逃脱，而杰克也因此遭到了被情报局软禁的命运。不幸的是，杰克的仁慈并没能挽救仕达罗妻儿的性命，悲愤之中，仕达罗绑架了凯瑟琳。在狱中听闻此噩耗的杰克当即下定决心，不惜越狱也要将仕达罗捉拿归案。",
