    "year": "1984",
    "description": "陈凯歌导演首作，影片改编自柯蓝的小说《深谷回声》，讲述了陕北农村的贫困女孩，因父亲定下的娃娃亲，无法逃脱厄运的悲惨故事。由中国第五代导演的两位代表人物陈凯歌执导，张艺谋摄影的本片，被誉为两人巅峰的会师之作，本片在1985年第五届中国电影金鸡奖上荣获最佳摄影奖，同年在瑞士洛迦诺和东京等海外电影节上斩获了多项大奖，标志着中国第五代导演在国内外影坛的真正崛起。",
