    "description": "重庆一家濒临倒闭的工艺品厂在拆除旧厂房时，意外从厕所里发现了一块价值不菲的翡翠。为了缓解经营困境，厂里决定举办翡翠展览，并由保卫科长包世宏负责看守。没想到消息传开后，国际大盗麦克和本地一伙小偷都盯上了这块宝物，各自使出不同手段试图将其弄到手。包世宏一边想方设法保护翡翠，一边与这些不速之客斗智斗勇。随着几路人马不断交错，一场围绕翡翠展开的明争暗斗也变得越来越失控……",
