    "type": "movie",
    "year": "2009",
    "description": "职业自行车手耿浩在一次全国锦标赛中以0.01秒之差屈居亚军，随后又因商人李法拉的算计导致药检呈阳性，被终身禁赛，人生从此跌入谷底。多年后，耿浩靠运送水产维持生活，并照顾中风的教练，而李法拉早已靠推销补品“肾白银”发了财。教练去世后，耿浩决定找李法拉讨个说法；与此同时，李法拉为了摆脱妻子找来两名业余杀手，一伙台湾黑帮也正与泰国毒贩秘密交易。原本毫无关系的几路人马，因为一连串阴差阳错不断相遇，彼此的计划也被一次次搅乱，一场越来越失控的荒诞追逐由此展开……",
