    "description": "秦风收到表舅唐仁即将结婚的消息，专程赶到纽约参加婚礼，却很快发现所谓婚礼只是唐仁骗他前来的借口。原来纽约唐人街的七叔重金悬赏，要为惨遭杀害的孙子寻找真凶，来自世界各地的侦探也因此齐聚纽约展开较量。面对离奇的凶案和丰厚的赏金，原本准备离开的秦风重新产生兴趣，与唐仁再次组成搭档。随着调查展开，他们逐渐发现眼前的案件并非孤立事件，一场更加复杂危险的连环谜案也随之浮出水面……",
