    "type": "movie",
    "year": "2014",
    "description": "本片由5段故事组成。北漂屌丝男陈锋（陈思诚 饰）在好友（郭京飞 饰）的告别单身派对上对白领沈彦（佟丽娅 饰）一见钟情，随后两人开展了热恋，不料不久后两人未婚先孕，二人准备结婚但却遭到了沈彦母亲的反对，此时沈的有钱前男友洪江（耿乐 饰）又再次出现了。与此同时陈锋的老板 吴峥（王学兵 饰）由于出轨被老婆张蕾（余男 饰）发现，愤怒的张蕾深夜画着浓妆走出了家门……张蕾的老板刘辉（梁家辉 饰）与佳玲（刘嘉玲 饰）秘密来到希腊偷情，却不料两人因为意见不合险些吵翻。刘辉的女儿阳阳（欧阳娜娜 饰）发现隔壁班的男生（刘昊然 饰）经常跟自己搭乘同一辆车回家，意外认识后两人无话不谈，微妙的感情在两人心中产生。男孩的姥姥（斯琴高娃 饰）得了绝症，乐观的她决定给老伴（王庆祥 饰）找一个新的伴侣协助他走过余生，一名海归老太太（金燕玲 饰）走进了老两口的生活",
