    "description": "大学毕业后，杜乐莹只短暂工作过一段时间，便长期宅在家中，与外界逐渐疏远。一次与妹妹的激烈冲突让她决定离开家，尝试独自生活，却又接连遭遇爱情、亲情与现实的打击。阴差阳错之下，乐莹结识了拳击教练昊坤，也第一次真正接触到拳击。在一次次跌倒与挫折中，这个早已习惯随波逐流的女孩开始想要为自己认真活一次，而属于她的人生也由此悄然发生改变……",
