    "description": "曾经叱咤风云的拉力赛车手张驰，因为五年前的一次违规赛车被禁赛，从赛场巅峰跌入人生谷底。终于等到禁赛期结束后，他重新找到亲如兄弟的领航员孙宇强，决心重返赛场，再次挑战巴音布鲁克拉力赛。然而想要真正回归，他还要重新考取驾照、筹备赛车并寻找赞助，每一步都困难重重。与此同时，禁赛这些年里，新秀车手林臻东已经迅速崛起。当昔日冠军重新站上熟悉的赛道，他不仅要面对现实留下的重重阻碍，也将迎来新一代强手的挑战……",
