    "description": "被浪荡父吴仁腾抛弃小岛上的年轻人吴仁耀，与奶奶相依为命，梦想能找一份与所热爱的摩托车有关的工作；为了追求打工妹周欢颂而结识了她的哥哥周欢歌，并加入了他的车队「不败传说」──虽然从来没有赢过，孤独的阿耀却终于有了朋友。  好景不常，一次意外让阿耀与欢颂背负巨款债务，两人不得不离乡背井前往城市打拼，渴望互相取暖却又想各自独立的两人，即将迎接一场未知旅途；直到阿耀的一身摩托车特技，遇上一个自己都意想不到的机会，身处现实的洪流中，阿耀会如何选择？他们的未来又该何去何从？",
