    "description": "人到中年的夏洛事业无成，一直靠妻子马冬梅维持生活。参加学生时代暗恋的校花秋雅的婚礼时，看着昔日同学一个个事业有成，他虚荣心作祟，在酒后大闹婚礼，与马冬梅发生激烈冲突。混乱过后，夏洛竟意外回到了1997年的学生时代。面对重新来过的人生，他决定弥补曾经的遗憾，不仅大胆追求秋雅，还凭借对未来的记忆一步步改变自己的命运。曾经遥不可及的爱情、名声与成功似乎都变得唾手可得，然而当梦想中的人生逐渐成为现实，夏洛也开始发现，得到自己曾经渴望的一切，并不一定意味着真正的幸福……",
