    "description": "混迹于西虹市丙级足球队的守门员王多鱼因为比赛失利被球队开除，正为生计发愁时，却突然得知自己有机会继承远房二爷留下的一笔巨额遗产。不过想要获得全部财富，他必须先完成一个看似荒唐的考验：在一个月内合法花光10亿元，同时还不能向任何人透露真正的规则。王多鱼于是带着好友庄强，在财务夏竹的监督下开始想方设法花钱。本以为挥霍财富再简单不过，他却很快发现，想在重重限制之下把钱真正花出去远比想象中困难，而这场突如其来的财富游戏也开始不断考验他的选择……",
