    "description": "西虹市富豪马成钢与妻子春兰担心优渥的生活会让儿子马继业失去独立成长的能力，于是隐瞒真实家境，搬进破旧的大院，在儿子面前扮成生活拮据的普通家庭。为了把马继业培养成他们心目中的理想接班人，夫妻二人精心设计他的生活与教育，甚至让身边的人共同参与这场漫长的“养成计划”。从小在困苦环境中长大的马继业也不负期待，学习优秀、生活独立，并逐渐形成了自己对未来的憧憬。然而随着年龄增长，他开始察觉身边越来越多不合常理的细节，也慢慢意识到自己熟悉的生活似乎并不像表面看起来那么简单……",
