    "type": "movie",
    "year": "2002",
    "description": "多年前，黑帮成员刘建明奉韩琛之命进入警队，逐渐成为一名真正的警察；与此同时，警校学员陈永仁则接受秘密任务，被安排潜入韩琛的犯罪集团。多年过去，两个人都在各自的身份中越陷越深：陈永仁渴望结束漫长的卧底生涯，重新以警察身份生活，而刘建明也开始对自己一直以来的选择产生动摇。一次警方针对韩琛的行动意外泄密，让警察与黑帮同时意识到自己的内部藏有卧底。为了保住身份，也为了找到潜伏在另一边的那个人，刘建明和陈永仁开始在彼此毫不知情的情况下展开一场危险的追查……",
