    "originalTitle": "辣手神探",
    "type": "movie",
    "year": "1992",
    "description": "袁浩云（周润发 饰）是一位办案勇猛、对朋友极讲义气的“辣手神探”，屡破奇案。他的目标是一个庞大的非法军火集团。该集团原由海叔（关海山 饰）掌控，但随着海叔年事已高，其势力被心狠手辣的新头目汪东源（黄秋生 饰）逐步取代。\r 警方卧底江浪（梁朝伟 饰）原是海叔的得力左右手。为取得汪东源的绝对信任，以便深入核心获取犯罪证据，江浪不得不亲手干掉海叔，以证明自己的“不二之心”。汪东源大喜，随即吸纳江浪为其头号马仔。\r 不知内情的袁浩云，将已成为黑帮核心的江浪视为必须铲除的死敌，两人多次交锋，拼得你死我活。然而，在激烈的对抗中，袁浩云逐渐察觉此人身份极可疑。最终，他得知江浪竟是身负重任的卧底同僚。\r 于是，一明一暗、性格迥异的两位警察——火爆直接的袁浩云与隐忍压抑的江浪，在身份揭露后决定联手。他们从生死相搏的对手，转变为背靠背作战的生死之交，共同向汪东源的军火帝国发起一场惊心动魄的终极决战。",
