    "year": "1995",
    "description": "至尊宝被月光宝盒带回五百年前，意外遇见紫霞仙子。紫霞与青霞本是如来佛祖座前日月神灯的灯芯，共用同一副身体却性格迥异。紫霞曾立下誓言，谁能拔出她手中的紫青宝剑，谁就是她命中注定的意中人。不料至尊宝无意间拔出了宝剑，从此被紫霞认定为自己的真命天子。然而，此时的至尊宝仍一心想找到白晶晶，并设法回到原来的时空。随着牛魔王等人相继卷入其中，至尊宝发现自己不仅要面对错综复杂的感情，也不得不重新面对自己与孙悟空之间无法逃避的命运……",
