    "type": "movie",
    "year": "1995",
    "description": "五百年前，孙悟空因犯下大错遭到观音菩萨惩罚，唐三藏为救徒弟甘愿牺牲自己。五百年后，孙悟空转世成为斧头帮帮主至尊宝，过着与前世毫无关系的山贼生活。一天，春三十娘与白晶晶突然来到五岳山，寻找转世后的唐三藏，至尊宝一伙也因此被卷入妖怪之间的争斗。更让至尊宝意外的是，白晶晶与五百年前的孙悟空似乎还有一段未了的情缘。随着自己的身世逐渐浮出水面，一件能够穿越时空的宝物“月光宝盒”也将至尊宝引向一段意想不到的命运……",
