    "description": "姜子牙与姬发回到西岐后，一场家园保卫战随之迫近。奉商王殷寿之命，邓婵玉、闻仲率领魔家四将及殷商大军征伐西岐；姬发一方则得到殷郊、雷震子、杨戬、哪吒等人的相助，并集结西岐百姓共同守卫家园。随着两军交锋，凡人之间的战争也逐渐演变为法术与神力的较量，而围绕“封神榜”的争夺仍在继续。面对步步逼近的殷商大军，西岐迎来了前所未有的危机……",
