    "description": "李逍遥是渔村店小二，人如其名，自在逍遥，精灵古怪，生活无所拘束。一段机缘巧合与隐居在仙岛躲避追杀的南诏公主赵灵儿相遇，因一面之缘，结下姻缘。李逍遥护送赵灵儿回苗疆寻母，一番误闯，半路杀出了刁蛮千金林月如。从此，三人的命运紧紧相系，难割难舍。南诏国拜月教主妄图侵占中原，为达目的不择手段。该剧以其独特的方式为观众讲述了一段有关李逍遥与赵灵儿以及林月如等人之间的恩爱情仇，拯救苍生的神话故事。",
