    "originalTitle": "仙剑奇侠传三",
    "type": "tv",
    "year": "2009",
    "description": "渝州城里乐观的景天渴望成为蜀山大侠。唐家堡大小姐雪见发现了唐门中有人勾结霹雳堂谋害爷爷，而幕后主脑居然来自蜀山，于是求助于欢喜冤家景天。蜀山的锁妖塔被来自魔界的重楼拔走了千年魔剑，打开了塔门，群妖滋扰凡间，景天与蜀山大弟子长卿为伸张正义并肩而战。原来景天的前身是神界的飞蓬将军，而长卿则是追随景天多年的神剑的化身。女娲的后人紫萱追着她的前世爱人长卿也来到蜀山，可是长卿已不记得她。只要能取得五颗灵珠，就能再次封印蜀山锁妖塔，重建秩序。众人在寻找五灵珠的过程中，互相扶持，患难中获得真情，历经重重困难后，众人终于取得五灵珠，战胜了邪剑仙，维护了人间的和平。历炼之后长卿和紫萱选择了放下，为大爱牺牲个人的小爱，景天则选择放弃恢复神界的身份，带着至爱雪见吃玩到老，对他而言没有任何东西比这一刻更真实，活在当下。",
