    "description": "故事发生在抗日战争如火如荼的关键阶段，汪伪政府投敌叛国，华夏大地民不聊生，炎黄子孙的命运危在旦夕。上海明氏企业的董事长明镜胸怀赤诚，暗中资助中国共产党。她的弟弟明楼则在军统担任特工，行踪诡秘。姐弟俩的弟弟明台饱读诗书，本无心政治，谁 知却在飞赴香港途中被军统高官王天风绑架招揽。万般无奈之下，明台只能隐姓埋名接受培训，并最终成为军统驻上海站的一名特工。在接下来的行动中，他与中共锄奸小组的程锦云多有配合，两人在行动中也培养出非凡的信任与感情。国内局势风云变化，这两个年轻人则将面临着命运的严苛考验。",
