    "type": "tv",
    "year": "2018",
    "description": "盛家六姑娘盛明兰从小聪颖貌美，却遭遇嫡母不慈、姐妹难缠、父亲不重视、生母被害去世的困境。她藏起聪慧，掩埋锋芒，忍辱负重在逆境成长，在万般打压之下依然自立自强，终历尽艰难为母报仇。在这一过程中，盛明兰结识了宁远侯府二公子顾廷烨。顾廷烨帮过盛明兰，也刻薄地对待过盛明兰，他见过盛明兰软弱表皮下的聪慧锐利，也见过她刚强性格中的脆弱孤单，对她早已倾心。朝廷风云变幻，在顾廷烨的拥戴下，赵家旁支宗室子弟被立为太子，顾廷烨拿着勤王诏书，大破反贼，而后拥立新帝，成为新朝第一功臣。而后，顾廷烨略施巧计娶了盛明兰为妻。盛明兰婚后管家业、整侯府、铲奸佞，夫妻二人解除误会建立了深厚的感情，最终盛明兰与丈夫一同协助明君巩固政权，二人也收获了美满的人生。",
