    "description": "20世纪90年代，江南某个小镇，河边发生了一桩离奇凶案，独居的幺四婆婆被人杀害。刑警队长马哲带着同事展开调查，一只遗落在现场的女士手提包和其中的磁带，将他们引向一个个看似与案件有关的人，而被幺四婆婆收养的疯子也逐渐成为重点怀疑对象。就在案件似乎即将找到答案时，新的死亡再次发生，原本清晰的线索开始变得扑朔迷离。面对局长要求尽快结案的压力，马哲却始终无法说服自己接受眼前的答案，并在不断追查中逐渐陷入荒诞、不安以及真假难辨的记忆与幻象之中……",
