    "description": "刑满释放不久的殡葬师莫三妹，在一次出殡中意外遇见了失去亲人的孤儿武小文。无法理解死亡的小文就此缠上了莫三妹，给这个本就麻烦不断的男人带来了一连串意想不到的生活难题。一个玩世不恭，一个倔强天真，毫无血缘关系的两人在一次次争吵与相处中逐渐产生了特殊的情感。小文的出现，也让原本对生活和殡葬职业满不在乎的莫三妹，开始重新思考亲情、死亡与人生真正的意义……",
