    "description": "高考临近，性格内向的高三学生陈念一心只想考上理想的大学，离开眼前压抑的生活。然而，同校女生胡小蝶的意外坠楼打破了原本紧张却平静的备考生活，也将长期隐藏在校园里的霸凌逐渐暴露出来。此后，陈念也成为以魏莱为首的几名学生欺凌的对象。在她最孤立无援的时候，生活在街头的少年小北意外闯入了她的世界。两个原本毫无交集的少年逐渐彼此靠近，小北也开始用自己的方式保护陈念。高考越来越近，而围绕他们的危险却并未停止，两个人的命运也因此紧紧联系在一起……",
