    "description": "在其令人迷醉的第三部作品中，富有远见的导演毕赣向着纯粹梦境的领域发起了最深入的探索。在一个人类为换取永生而遗弃了梦境的世界里，一个做梦的怪物（易烊千玺 饰）踏上了一场千变万化的奥德赛之旅——穿越幻象、美丽与恐惧，横跨一个世纪的电影史，直至时间的尽头。影片以五个想象瑰丽的篇章展开，囊括从默片时代表现主义到黑色电影，再到以毕赣标志性长镜头拍摄的迷狂吸血鬼爱情故事。本片是一部想象力惊世骇俗的作品，其中，电影是通往无意识的终极入口。[标准收藏]",
