    "originalTitle": "青云志",
    "type": "tv",
    "year": "2016",
    "description": "张小凡本是一介平凡的少年，在草庙村过着平静的生活。然而，一场屠村惨案让张小凡失去了父母和朋友，并在机缘巧合之下得到了珍贵的嗜血珠。和幸存的好友林惊羽一起，张小凡来到青云门拜师学艺，他满心仇恨想要替双亲报仇，殊不知这盲目的戾气会领他步入歧途。一眨眼入师门已经数年，可张小凡却一事无成，某日，他意外得到了法宝魂摄，哪知魂摄和嗜血珠融为一体，成为了张小凡最得力的武器。张小凡和陆雪琪等一行人结伴调查魔教下落，期间，张小凡三番五次救陆雪琪于危机之中，陆雪琪芳心暗许。之后，张小凡又结识了名为碧瑶的女子，两人情愫渐生，可是碧瑶的父亲是十恶不赦的鬼王，为了铲除青云门，鬼王设下了一个又一个圈套。青云门弟子在鬼王宗宗主之女碧瑶死后，为了复活碧瑶，化身鬼厉，流浪世间，寻找复活之法。",
