    "description": "王薄和王丽是一对以偷盗为生的恋人搭档。得知自己怀孕后，王丽开始厌倦这种漂泊不定的生活，希望就此收手，而王薄却并不认同她的选择。返程途中，两人遇见了带着多年积蓄回乡盖房娶妻的农村青年傻根。傻根单纯地相信“天下无贼”，毫无戒心地带着全部家当踏上旅程，他的纯朴逐渐触动了王丽，也让王薄产生了不同的想法。与此同时，以黎叔为首的另一伙扒窃团伙早已盯上傻根的钱。围绕着这个对人心毫无防备的年轻人，一场盗贼之间的明争暗斗也在列车上悄然展开……",
