    "year": "2007",
    "description": "1948年淮海战役期间，九连连长谷子地率领47名战士执行阻击任务，为大部队撤退争取时间。团长刘泽水命令他们以“集结号”为撤退信号，只要没有听见号声，就必须坚守阵地。面对远强于己方的敌军，九连伤亡不断，排长焦大鹏临终前声称自己听到了集结号，但谷子地始终没有听见，于是决定继续死守。惨烈战斗过后，九连除谷子地外全部牺牲，而因为部队番号变更、遗体未能得到确认，这些战士后来只被登记为“失踪”。幸存下来的谷子地始终无法放下这段往事，为了替47名战友找回应有的荣誉，也为了弄清当年的集结号究竟是否响起，他开始了一场漫长而执着的寻找……",
