    "type": "movie",
    "year": "2010",
    "description": "春节将近，玩具集团老板李成功准备返回长沙与家人过年，同时还要面对情人催促他结束婚姻的压力。机场里，他遇到了同样前往长沙讨要欠款的挤奶工牛耿。一个精明世故，一个耿直憨厚，两人从见面开始便格格不入。没想到大雪让飞机返航，此后无论改乘火车、大巴还是其他交通工具，两人总会阴差阳错地再次碰到一起，各种意外也接连而来。一路的狼狈让李成功对牛耿不胜其烦，但这个始终乐观真诚的陌生人，也在不知不觉间开始改变他对生活和人与人关系的看法……",
    "cover": "https://image.tmdb.org/t/p/w500/nfpdBNa27d3XjsCmXgZmUW2EaLT.jpg",
