    "description": "被视为天赋异禀的少年武者萧炎（吴磊饰），九岁时母亲古文心（李若彤饰）被族人强行带回家族囚禁，父亲萧战（于荣光饰）讳莫如深。萧炎的母亲给了萧炎一枚纳戒，但是却令萧炎的功力减弱无法修炼，早已订好婚约的家族也来退婚，令萧家蒙受奇耻大辱。萧炎无意中唤醒了戒指的主人药尘（陈楚河饰）老人，在药尘老人的帮助下，萧炎的武功进步惊人。萧炎进入迦南学院学习艺技，在这里结交了一群良师益友，再次引起了敌人的注意。一次特殊修炼中，萧炎遭到陷害，死里逃生后，发现他的家族也遭到了灭顶之灾。为了世间和平，萧炎毅然选择了只身一人向邪恶的势力发起挑战。最后联手女侠萧薰儿（林允饰），共同战胜了强敌。",
