    "originalTitle": "雪中悍刀行",
    "type": "tv",
    "year": "2021",
    "description": "胸藏锦绣的北凉王世子徐凤年，在其父徐骁的殷殷期盼下，终成大器。千里历练，三进三出，徐凤年劣马黄酒行走在未知的江湖，虽道路漫长且阻，无情杀机常伴左右，可他依然坚忍走完全程修成天人大长生境界。在行走江湖的过程中，徐凤年一路游历江湖为母仇而奋斗，除不断提高自身的武术修为，还收拢众多江湖人士。最终成为北凉王。\n\n时值北莽入侵、中原起烽烟，行走江湖归来的徐凤年带领北凉铁骑抗击北莽，在朝廷算计下，北凉三十万铁骑死伤大半依旧惨胜，三十万墓碑历历在目，最终离任北凉“死于”皇宫，隐姓埋名携红颜知己游戏江湖。",
