    "description": "唐天宝年间，长安小吏李善德人到中年，仕途多年仍默默无闻，还要为一家人的生计精打细算。一次突如其来的任命似乎让他迎来了转机，他被派去担任“荔枝使”，却很快发现这并不是什么轻松的肥差，而是一项几乎不可能完成的任务：将远在岭南的新鲜荔枝跨越千里运抵长安。荔枝极易腐坏，沿途路程、驿站、人力和时间无一不成为难题，而官场中的层层阻碍又让这趟差事愈发艰难。为了保住性命，也为了给家人一个交代，李善德只得赶赴岭南，从一颗荔枝开始寻找完成这场极限转运的可能……",
