    "originalTitle": "法医秦明",
    "type": "tv",
    "year": "2016",
    "description": "龙番市刑警队长林涛，与法医科科长秦明是多年的老朋友。秦明的助理因不堪忍受秦明的古怪脾气打报告辞职。痕检科的李大宝被借调加入工作小组。起初秦明对身为女生的大宝不信任，但倔强的大宝在破案中，体现出了相当不错的推理和观察能力，并且嗅觉极度灵敏，挑剔的秦明决定留下大宝。龙番警局的铁三角也初告形成。以这起“油爆奇案”为开端，秦明、大宝和林涛接连破获了各种匪夷所思的案件。\n\n本剧改编自秦明所著《法医秦明》系列悬疑小说中的《第十一根手指》。此系列小说先后由漓江出版社、湖南文艺出版社出版，现已出版万象卷六部：《尸语者》、《无声的证词》、《第十一根手指》、《清道夫》、《幸存者》、《偷窥者》，以及众生卷两部：《天谴者》、《遗忘者》。该系列已被改编成多部网络剧，分别为《法医秦明》、《法医秦明2：清道夫》、《法医秦明之幸存者》、《尸语者》、《法医秦明之无声的证词》等。",
