    "originalTitle": "你是我的城池营垒",
    "type": "tv",
    "year": "2021",
    "description": "在医院联合警校组织的应急救援演练中，特警精英邢克垒结识了住院医生米佧。随着接触增加，二人关系由开始的势同水火到互相了解，邢克垒对米佧心动不已。突如其来的地震，打破了生活的平静。米佧和邢克垒临危受命前往灾区，两人在救援工作中忠于职守，完美地诠释了公安特警和人民医生在国家危难面前视死如归的精神与意志。随着救灾工作的不断推进，米佧从邢克垒身上看到了公安民警的大义凛然，邢克垒也从米佧身上看到了人民医生的仁心仁术，从而越发理解对方身上背负的职责与使命。身为公安民警和医生，二人再次同舟共济，愿为彼此筑一座城池，忠坚不移，守护对方，以及他们身后千千万万的人民 。",
