    "description": "因为一场联姻擢选，来自天南海北的女孩们齐聚新川。韬光养晦的新川六少主尹峥，与只想努力落选、在老家安逸度日的李薇意外结缘，共同开启了一段状况百出却又相映成趣的新生活。随着尹峥开府、上朝，二人逐渐口味相投、心意相通，携手共度三餐四季，并与其他性格命运各异的兄弟姐妹们相伴成长，一起书写着新川大家庭的温暖日常。",
