    "year": "2024",
    "description": "人到中年的检察官韩明早已褪去往日锋芒，眼下最关心的是结束挂职、顺利转正。然而，一起发生在康村的伤人案打破了他平静的生活：村民王永强为保护妻子捅伤长期欺压他们的刘文经，却因此面临严厉的刑事追责。女检察官吕玲玲顶住各方压力，坚持重新审视案件真相。与此同时，韩明的儿子韩雨辰因制止校园霸凌而打伤同学，也让韩明在家庭中面对另一场关于“该不该还手”的争论。两起看似不同的事件逐渐交织在一起，也迫使这个一心求稳的检察官重新思考法律、公平与正义的边界……",
