    "description": "花千骨（赵丽颖 饰）曾经被长留上仙白子画（霍建华 饰）所救，因此芳心暗许，长大之后，她千里迢迢前往长留仙山，想要找到当年的恩人。经过重重的考验和比试，花千骨终于成为了白子画的座下弟子，然而她并不知道的是，自己命格诡异，注定要成为白子画的生死劫，而花千骨和白子画两人在相处的过程中，早已经产生了超越了师徒的感情。堕仙夏紫薰（蒋欣 饰）亦深爱着白子画，不愿看到爱人为花千骨白白送死的她企图下毒杀死花千骨，没想到最后中毒的却是白子画。为了挽救白子画的性命，花千骨想尽了一切方法，并且在无意之中获得了洪荒之力，为日后的悲剧埋下了伏笔。",
