    "originalTitle": "老九门",
    "type": "tv",
    "year": "2016",
    "description": "镇守在长沙的九大家族人称“老九门”，名号之响无人不知无人不晓。其中，九门之首张大佛爷张启山（陈伟霆 饰）奉命调查鬼车和神秘矿山之谜，带着搭档齐铁嘴（应昊茗 饰），两人向出生于考古之家的戏曲名伶二月红（张艺兴 饰）求助，无奈二月红为了照顾病重的妻子丫头（袁冰妍 饰），早已经洗手不干。\n\n为了引二月红再度出山，张启山和齐铁嘴北上远赴新月饭店，为丫头求药。之后，张启山结识了新月饭店的大小姐尹新月（赵丽颖 饰），两人之间渐渐产生了情意。尽管丫头最终还是不治身亡，但二月红意外发现矿山之谜和自己的家族前辈之间有着牵扯不清的关系，同时亦隐藏了一个日本方面谋划的惊天阴谋。",
