    "description": "　　传说中的神话奥汀大陆分为水、风、火、地四个国家，每个国家都有精通魂术的人，其中最厉害的七个被称为王爵。水国普通男孩麒零（陈学冬 饰）离奇地被七度王爵银尘（吴亦凡饰）收为使徒，卷入了这场魂术的风暴，水国隐藏的秘密也渐渐浮出水面。在奥汀大陆这个神秘的世界里，西之亚斯兰帝国七度王爵银尘寻找到自己的使徒麒零，却无意中发现了上代一度王爵吉尔伽美什可能还活着的秘密，于是义无反顾的投入到追寻之中，而与此同时作为侵蚀者的王爵幽冥（陈伟霆 饰）、特蕾娅（郭采洁 饰）也收到了对银尘和鬼山莲泉（范冰冰 饰）等人的杀戮红讯。一场王爵和使徒们为了真相和荣誉的战役一触即发。",
