    "description": "国际大都会上海，霓虹闪烁，人头攒动。多少年轻人从四面八方云集十里洋场，追寻着似乎触手可及的事业、爱情和梦想。在一个名为“欢乐颂”的小区，居住着五个年龄相仿的女孩子，分别是合租一套房的供职外企的“胡同公主”樊胜美（蒋欣饰 ）、家境良好的乖乖女关雎尔（乔欣 饰）、来自小城市的普通上班族邱莹莹（杨紫 饰），另外还有集美貌、智商事业于一身的海归女安迪（刘涛 饰）和古灵精怪的富二代曲筱绡（王子文 饰）。俗话说“三个女人一台戏”，更何况是五个有着不同性格、背景和人生经历的青春女孩。她们相互碰撞，彼此依偎，共同讲述了繁华城市中女孩子们的奋斗物语。",
