    "originalTitle": "战长沙",
    "type": "tv",
    "year": "2014",
    "description": "该剧改编自同名小说，以中国近代史上著名的“长沙会战”为背景，借由长沙城一户普通的“胡”姓人家在战争中的命运浮沉，展现出战火的无情以及在日军蹄铁的侵略下，中华儿女奋起抗战的不屈精神。1938年10月，日军攻陷武汉，长沙危在旦夕。城中茶园巷的胡家人，在孙女婿薛君山的支持下，千方百计为胡家最宠爱的一对龙凤胎湘湘和小满安排退路。薛君山先将湘湘介绍给留洋归来保卫长沙的顾清明，可惜生性泼辣的湘湘和心高气傲的顾清明一见面便势同水火，薛君山只好另选人家。订婚当日，蒋介石密令火烧长沙，由于指挥失当，长沙大火酿成巨大灾难，繁华的古城毁于一旦，很多睡梦里来不及跑的人被活活烧死，包括湘湘的未婚夫一家。就在这样一片焦土上，各地英雄儿女齐聚长沙，和湖南人民一起艰难地阻挡敌人的铁蹄，胡家人也在这场劫难中演绎了一幕幕悲欢离合的故事。",
