    "title": "白幽灵传奇之绝命逃亡",
    "originalTitle": "Outcast",
    "type": "movie",
    "year": "2014",
    "description": "　　影片讲述了十字军战士雅各布和加蓝，来到遥远而又神秘的东方，遭遇被追杀的东方公主莲和小皇子昭的故事。饱受战争折磨的英国骑士雅各布（海登·克里斯滕森饰）为逃离十字军战争的痛苦记忆流落至世界另一端的东方，然而，当他答应保护皇室姐弟莲（刘亦菲饰）和昭的时候，他发现自己在遥远的异乡再掀刀光剑影。星（安志杰饰）是莲的皇兄，他生性残暴，从皇位继承人昭手中篡夺了皇位，江山社稷岌岌可危。为了让天下重归太平，雅各布护送被追杀的姐弟俩踏上了一条险象环生的逃亡之路。在已经落草为寇的加蓝的帮助下，这些沦落之人要面临的不仅是危机四伏的官兵追杀还有天下最厉害的剑客——星。",
