    "originalTitle": "天龙八部",
    "type": "tv",
    "year": "2003",
    "description": "北宋年间宋、辽、西夏对立，丐帮帮主乔峰被丐帮副帮主马大元之妻康敏所害，被武林所不齿，乔峰为查出真相为自己平反开始了调查之路，却引发了更大的纠葛。他在调查途中遇上了大理段家风流倜傥的世子段誉以及看似木讷却宅心仁厚的少林小和尚虚 竹，三人意气相投结成兄弟。乔峰认识了阿朱、阿紫两姐妹；段誉痴情于王语嫣，遇见了众多红颜知己；虚竹遭遇了神秘的梦姑。面对乱世，三人开始了非同寻常的江湖生涯，遇见了诸如天山童姥、慕容复、四大恶人等各色高手，生死情仇、爱恨别离、民族大义在因缘际会中施展。",
