    "originalTitle": "四大名捕",
    "type": "movie",
    "year": "2012",
    "description": "　　巍巍京城，气势磅礴。时有捕神（成泰燊 饰）率领的六扇门，高手云集，作风凌厉，成为朝廷只手遮天的人物。是时京城伪造铜币泛滥，六扇门头号捕快冷血（邓超 饰）策划抓捕疑犯，结果在醉月楼与另一组人马大打出手。对方是诸葛正我（黄秋生 饰）统领的神侯府，手下更有无情（刘亦菲 饰）、铁手（邹兆龙 饰）等身怀绝技的高手。捕神对神侯府的目的颇有猜疑，遂假意赶走冷血，令其潜入神侯府调查诸葛之真实目的。在此之后，冷血与无情、铁手以及江湖中人追命（郑中基 饰）组成四大名捕，声名显赫，而来自六扇门的姬遥花（江一燕 饰）似乎又暗藏不可告人的秘密与阴谋…… 　　本片根据温瑞安同名武侠小说改编。",
