    "tmdbType": "movie",
    "title": "风声",
    "originalTitle": "风声",
    "type": "movie",
    "year": "2009",
    "description": "1942年10月10日，汪伪政权举行国民政府庆典，接连发生的军政要员遇刺事件引起日方高度重视。日军特务机关长武田经过调查，发现负责传递情报、代号“老鬼”的地下党就潜伏在剿匪司令部内，于是将最有可能接触机密电报的五名嫌疑人带到封闭的裘庄：剿匪大队长吴志国、司令侍从官白小年、译电组组长李宁玉、行政收发专员顾晓梦以及军机处长金生火。武田只有五天时间找出“老鬼”，为此不断对五人进行审讯、试探和施压；而被困其中的每个人为了洗清嫌疑，也在暗中观察着其余四人。随着猜疑不断加深，裘庄逐渐成为一场真假难辨、人人自危的生死迷局……",
