    "description": "五年前的旧金山事件之后，帝王组织对泰坦巨兽的研究从未停止。位于61号基地的摩斯拉突然孵化，艾玛·罗素博士利用声波装置与它建立联系，却遭到艾伦率领的雇佣兵袭击。对方企图利用这套装置唤醒沉睡在冰层中的远古巨兽基多拉，而事件很快超出所有人的控制。随着拉顿等泰坦巨兽在世界各地相继苏醒，人类再次面临前所未有的危机。为阻止灾难继续扩大，马克·罗素与芹泽博士等人加入追踪，而哥斯拉也再次现身，与基多拉之间一场决定巨兽秩序的较量逐渐展开……",
