    "description": "有着一双蓝灰色眼睛的小百合（章子怡 饰）出生于贫穷小渔村，被卖到京都一家知名的艺妓馆。小百合在那里学习了舞蹈、茶艺等，渐渐成为当地头牌艺妓，同时也不断受到京都第一红妓初桃（巩俐 饰）的压迫与挑战。一个偶然的机会，全日本最美丽、知名的艺妓真美羽（杨紫琼 饰）要认小百合为“妹妹”，此举从此改变了小百合的一生……",
