    "type": "movie",
    "year": "2018",
    "description": "　　未来，人们对资源的需求越来越大，可是地球上的资源已经不能再满足人类。于是地球上爆发了资源危机，并险些引发战争。唯一能阻止战争的只有空间站上的粒子加速器，如果实验成功，粒子加速器成功运转，那么它就能让人们用上源源不断的资源。可是在一次粒子加速器意外事件后，地球整个消失了，空间站上的宇航员开始试图弄清楚在他们身上发生了什么。但随着事情的一点点深入，真相慢慢浮现，更奇怪的事情也随之出现。",
