    "originalTitle": "Blackhat",
    "type": "movie",
    "year": "2015",
    "description": "中国香港和美国洛杉矶同时发生了导致严重后果的黑客入侵事件，中国政府和美国联邦调查局决定联手，找到事件的真相。经过调查，黑客在犯罪过程中使用了远程访问工具，而程序的编写者是一位名为尼古拉斯（克里斯·海姆斯沃斯 Chris Hemsworth 饰）的神秘男子，身为网络高手的他此时正身陷囹圄。  　　陈大伟（王力宏 饰）是负责此案的军官，他和妹妹（汤唯 饰）远赴洛杉矶，在特工卡罗尔（维奥拉·戴维斯 Viola Davis 饰）的帮助下寻得了尼古拉斯的踪迹。两人和尼古拉斯之间达成了一个交易，如果尼古拉斯能够帮助他们找到黑客事件的幕后真凶，那么尼古拉斯就将重新获得自由。",
