    "type": "movie",
    "year": "2018",
    "description": "毕赣令人目眩神迷的第二部作品，是一部迷幻而充满黑色电影气质的惊艳之作。影片讲述一个失落的灵魂（黄觉 饰）为寻找记忆中失踪的女人（汤唯 饰）而踏上征程。循着线索穿越贵州，他邂逅了一系列形形色色的人物，其中包括由台湾巨星张艾嘉饰演的脾气古怪的美发师。当搜寻将他引至一间破败的影院时，影片将他——以及我们——抛入一段史诗般反重力的段落：一场沉浸式的、长达一小时的迷宫式梦境之旅，堪称现代电影的真正奇迹之一。作为中国有史以来最卖座的文艺片，本片印证了毕赣是当代最具胆识、最令人兴奋的作者导演之一。[标准收藏]",
