    "description": "《欢喜密探》是由和润影业、华山论剑影视文化传媒、包贝尔工作室首度联手芒果娱乐共同出品，包贝尔执导，包贝尔、柳岩、王鸥、包文婧领衔主演，赵丽颖、陈紫函、杨子姗、张歆艺等友情客串的古装网络剧。该剧讲述了顺治年间，混迹于扬州的小人物牛大宝遭遇意外无奈成为洪帮成员卧底于朝廷机关部门，与敌人斗智斗勇，从而引发一系列令人啼笑皆非的故事。\n\n该剧于2016年10月17日在优酷独播。",
