    "description": "　　为了给母亲治病，生长在大山里的青年张三斤带着母亲来到了车水马龙的繁华大都市深圳，在这里一边工作一边照顾母亲。一场意外中，张三斤结识了美丽的盲女花儿，花儿十分同情张三斤和他母亲的遭遇，主动来到了张三斤家，肩负起了照顾老太太的责任，令张三斤十分感动。最终，两人走到了一起，携手步入了婚礼的殿堂。  花儿自幼喜欢唱歌，她的声音空灵而又美好，常常能够打动人心。终于，花儿的才华得到了听众们的肯定，她一夜爆红，成为了家喻户晓的明星，而她的眼疾亦因此有了治愈的希望。虽然打心眼里替妻子感到高兴，但张三斤感受到的更多的是不安与自卑。",
