    "description": "2020年1月23日，农历腊月二十九，武汉宣布封城。本片聚焦这一特殊时刻，以温情和治愈为基调，刻画了普通市民守望相助、真挚动人的爱情群像。快递员阿勇（黄渤 饰），骑手武哥（贾玲 饰），钢琴老师叶子扬（朱一龙 饰），中年夫妇刘亚兰（徐帆 饰）和李宏宇（高亚麟 饰），退休老医生谢咏琴（吴彦姝 饰）和餐厅老板沛爷（许绍雄 饰），实习护士夏晓（周冬雨 饰），滞留旅客张哲（刘昊然 饰）和君君（乔欣 饰）。疫情下，爱给了他们挺身而出的勇气和力量。他们以笑做盾，以爱为矛，冲破凛冽寒冬和恐惧，勇敢拥抱。爱在武汉的烟火气下蔓延，抵御一切苦难，最终见证奇迹。",
