    "description": "唐喜（冯巩 饰）和妻子张芸（姜宏波 饰）结婚多年，夫妻两人之间感情一直十分要好。唐喜在光华纺织厂担任副工段长的职位，而张芸则在糖厂工作。因为工作上的出色表现，唐喜被升职成为了工长，然而这喜悦还未淡去，复杂的人事纠葛和他最不擅长的人情往来便令唐喜栽了个大跟头，不仅得罪了朋友，还遭到了降职，被调去看管根本无人问津的家属浴池，与此同时，糖厂倒闭，张芸亦丢了工作，家庭一下子就陷入了危机之中。\n\n　　然而唐喜是天生的乐天派，接连的打击并未让他一蹶不振。和好友大老黑一起，唐喜一门心思扑在自己的本职工作上，竟然将浴室经营的有声有色，可惜好景不长，唐喜倒在了又一波职工下岗的浪潮之下。",
