    "description": "传说在中国有个龙王，他睡觉的时候睫毛长到地里能够长出茶叶。龙王把法力封印在龙牌里，并把这种力量赋予了替他照料睫毛的白魔法大师和他的女儿成兰。黑魔法师联合恶毒的女巫，将白魔法大师和成兰关进了异国不同的监狱，企图让龙王臣服于他们。为了保护茶叶，龙牌被人藏了起来。没有人再修剪龙王的睫毛，随着睫毛加重，龙王陷入了沉睡。 英国绘图师格林偶然发现俄国沙皇是冒牌的，决心逃往东方，途中偶遇了成兰，二人结伴而行。依靠白魔法师和真正的沙皇彼得一世的帮助，他们获得了龙牌，并最终战胜了邪恶的女巫，守护一方平安。",
