    "description": "人过中年的魏平安生活潦倒，如今从事墓地销售工作。一天，他得知曾经的客户韩露在去世后遭到谣言污名化，连墓位也因此面临迁移。曾与韩露有过接触的魏平安相信她遭到了诬陷，决定查清谣言的源头，为她讨回清白。随着追查不断深入，谣言在网络上愈演愈烈，魏平安自己也逐渐被卷入误解与网暴之中。为了坚持自己认为正确的事，这个普通人开始了一场看似微不足道、却并不容易的较量……",
