    "type": "movie",
    "year": "1986",
    "description": "“独行侠”皮特·米切尔（汤姆•克鲁斯饰）的父亲是个战功显赫的老飞行员，他决心也要成为父亲那样的英雄。终于机会来了，他与军官“笨鹅”尼克·布拉德肖（安东尼•爱德华兹 饰）一起被派到了Top Gun训练基地接受最严格的飞行训练。可是，“独行侠”的训练并不像预想中顺利，他的成绩一直不令人满意，一起训练的”冰人”汤姆·卡赞斯基（方·基默饰）也对他也颇有微词。与此同时，“独行侠”遇到了美丽的女教官查莉（凯莉•麦吉利斯饰），两人对彼此暗生情愫，这令本来有些心灰意冷的“独行侠”重拾信心。在毕业前的一次训练中，“独行侠”搭档“笨鹅”再次同驾一机，但由于马达发生故障，“独行侠”与“笨鹅”被迫跳海，结果“笨鹅”不幸身亡。这次事件给“独行侠”带来了沉重的打击，本来因学业不顺就郁郁寡欢的他更加消沉了，甚至想要彻底放弃成为飞行员的梦想。“独行侠”最终能否克服心障重回蓝天？",
